import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"配置覆盖","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/configuration/overrides.md","filePath":"zh/kimi-code-cli/configuration/overrides.md"}`),a={name:`kimi-code-cli/configuration/overrides.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="配置覆盖" tabindex="-1">配置覆盖 <a class="header-anchor" href="#配置覆盖" aria-label="Permalink to “配置覆盖”">​</a></h1><p>Kimi Code CLI 有三个地方可以影响运行参数：配置文件、命令行选项、环境变量。它们不是简单的&quot;谁优先级高谁赢&quot;——三者面向不同场景，作用范围互不相同：</p><ul><li><strong>配置文件</strong> 保存长期偏好（模型、密钥、循环控制等），每次启动都生效</li><li><strong>命令行选项</strong> 做本次启动的临时切换，退出后失效</li><li><strong>环境变量</strong> 主要负责数据目录定位、OAuth 端点切换，以及少数运行时开关——<strong>不是配置字段的通用后备来源</strong></li></ul><p>这个区别很关键：很多人会在 shell 里 <code>export KIMI_API_KEY=xxx</code>，以为 CLI 会自动取到，但实际上不会。原因见下文<a href="#供应商凭证">供应商凭证</a>。</p><h2 id="环境变量的三类作用" tabindex="-1">环境变量的三类作用 <a class="header-anchor" href="#环境变量的三类作用" aria-label="Permalink to “环境变量的三类作用”">​</a></h2><p>环境变量按作用分三类，不能合并成一条线性优先级：</p><ol><li><strong>定位配置文件</strong>：<code>KIMI_CODE_HOME</code> 决定数据根目录，配置文件路径因此变为 <code>$KIMI_CODE_HOME/config.toml</code>。这一步先于其他所有解析，不是普通参数的后备来源。</li><li><strong>运行时开关</strong>：<code>KIMI_DISABLE_TELEMETRY</code> 等少量变量直接关闭对应子系统——即使 <code>config.toml</code> 里 <code>telemetry = true</code>，只要这个变量是真值，遥测就会被禁用。语义是&quot;额外禁用&quot;，不是&quot;普通覆盖&quot;。</li><li><strong>运行端点与诊断</strong>：<code>KIMI_CODE_OAUTH_HOST</code>、<code>KIMI_CODE_BASE_URL</code>、<code>KIMI_LOG_LEVEL</code> 等在 OAuth 或日志子系统初始化时读取。完整列表见<a href="/code/docs/kimi-code-cli/configuration/env-vars.html">环境变量</a>。</li></ol><h2 id="普通运行参数的优先级" tabindex="-1">普通运行参数的优先级 <a class="header-anchor" href="#普通运行参数的优先级" aria-label="Permalink to “普通运行参数的优先级”">​</a></h2><p>对模型别名、Plan 模式、yolo 模式、Skills 目录等普通运行参数，优先级从高到低：</p><ol><li><strong>命令行选项</strong>（<code>-m</code>、<code>--plan</code>、<code>--yolo</code> 等）：仅对本次启动生效</li><li><strong>用户配置文件</strong>（<code>~/.kimi-code/config.toml</code>）：保存长期偏好</li></ol><p>少数环境变量明确覆盖特定配置字段，例如 <code>KIMI_CODE_BACKGROUND_KEEP_ALIVE_ON_EXIT</code> 的优先级高于 <code>[background].keep_alive_on_exit</code>。这类例外在<a href="/code/docs/kimi-code-cli/configuration/env-vars.html">环境变量</a>和<a href="/code/docs/kimi-code-cli/configuration/config-files.html">配置文件</a>对应字段里都有标注。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p><strong>普通运行参数不会从 shell 环境变量取后备值。</strong> 供应商的 <code>api_key</code> / <code>base_url</code> 只从 <code>config.toml</code>（包括 <code>[providers.&lt;name&gt;.env]</code> 子表）读取，不会回退到 shell 里 <code>export</code> 的变量。唯一的例外是显式的 <code>KIMI_MODEL_*</code> 通道——详见<a href="/code/docs/kimi-code-cli/configuration/env-vars.html#用环境变量定义模型-kimi-model">用环境变量定义模型</a>。</p></div><p>目前 CLI 只读取一份用户级配置文件，没有项目级配置文件机制。需要在不同项目间隔离配置时，用 <code>KIMI_CODE_HOME</code> 指向不同的数据目录——见下文<a href="#典型场景">典型场景</a>。</p><h2 id="供应商凭证" tabindex="-1">供应商凭证 <a class="header-anchor" href="#供应商凭证" aria-label="Permalink to “供应商凭证”">​</a></h2><p>供应商凭证（<code>api_key</code>、<code>base_url</code>）有独立的解析规则，不走普通参数的优先级链。</p><p>对单个供应商，凭证按以下顺序解析：</p><ol><li><code>[providers.&lt;name&gt;].api_key</code> — 配置文件里直接写的密钥，优先级最高</li><li><code>[providers.&lt;name&gt;.env]</code> 子表里的对应键（<code>KIMI_API_KEY</code>、<code>ANTHROPIC_API_KEY</code> 等）— <code>api_key</code> 为空时才读这里</li><li>两者都缺 → 启动报错，提示该供应商缺少凭证</li></ol><p><code>base_url</code> 的解析方式相同：先读 <code>[providers.&lt;name&gt;].base_url</code>，再读 <code>[providers.&lt;name&gt;.env]</code> 里的 <code>*_BASE_URL</code> 键。</p><blockquote><p><code>[providers.&lt;name&gt;.env]</code> 子表只是配置文件里的一段 TOML，不会真正写入 shell 环境变量。仅当对应的直接字段（<code>api_key</code> / <code>base_url</code>）为空时，CLI 才会查这里。</p></blockquote><p>完整的凭证键名列表见<a href="/code/docs/kimi-code-cli/configuration/env-vars.html#供应商凭证键写在-configtoml-里">环境变量：供应商凭证键</a>。</p><h2 id="命令行选项" tabindex="-1">命令行选项 <a class="header-anchor" href="#命令行选项" aria-label="Permalink to “命令行选项”">​</a></h2><p>启动时传入的选项优先级最高，只对本次启动生效：</p><table tabindex="0"><thead><tr><th>选项</th><th>作用</th></tr></thead><tbody><tr><td><code>-S, --session [id]</code></td><td>恢复指定会话；不带 id 时进入交互式选择</td></tr><tr><td><code>-c, --continue</code></td><td>续上当前目录的上一次会话</td></tr><tr><td><code>-y, --yolo</code></td><td>自动批准普通工具调用，Agent 仍可能提问</td></tr><tr><td><code>--auto</code></td><td>以 auto 权限模式启动：完全自主，Agent 不会向用户提问</td></tr><tr><td><code>--plan</code></td><td>以 Plan 模式启动</td></tr><tr><td><code>-m, --model &lt;model&gt;</code></td><td>指定本次使用的模型别名</td></tr><tr><td><code>-p, --prompt &lt;prompt&gt;</code></td><td>非交互模式：执行单条提示词后退出</td></tr><tr><td><code>--output-format &lt;format&gt;</code></td><td><code>-p</code> 模式的输出格式：<code>text</code> 或 <code>stream-json</code></td></tr><tr><td><code>--skills-dir &lt;dir&gt;</code></td><td>替换自动发现的 Skills 目录（可重复，仅本次生效）</td></tr></tbody></table><p>互斥规则（违反时启动报错）：</p><ul><li><code>--output-format</code> 只能配合 <code>-p</code> 使用</li><li><code>--prompt</code> 不能同时用 <code>--yolo</code> 或 <code>--plan</code></li><li><code>--continue</code> 和 <code>--session</code> 不能同时用</li><li>非 prompt 模式下，<code>--yolo</code> 和 <code>--plan</code> 不能配合 <code>--continue</code> 或 <code>--session</code></li></ul><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p><code>--skills-dir</code> 是一次性替换，只影响本次启动。如需长期追加搜索目录，在 <code>config.toml</code> 里写 <code>extra_skill_dirs</code>（详见 <a href="/code/docs/kimi-code-cli/customization/skills.html">Agent Skills</a>）。</p></div><h2 id="典型场景" tabindex="-1">典型场景 <a class="header-anchor" href="#典型场景" aria-label="Permalink to “典型场景”">​</a></h2><p><strong>隔离测试环境</strong>——用单独的数据目录，避免污染主配置和会话：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KIMI_CODE_HOME</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.kimi-sandbox&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> kimi</span></span></code></pre></div><p><strong>一次性使用测试密钥</strong>——由于供应商凭证只从配置文件读，把测试密钥写进 <code>env</code> 子表：</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KIMI_API_KEY = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-test&quot;</span></span></code></pre></div><p><strong>跳过审批运行批处理任务</strong>：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yolo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;批量重命名以下文件...&quot;</span></span></code></pre></div><p><strong>临时进入 Plan 模式</strong>（若想永久生效，在配置文件设 <code>default_plan_mode = true</code>）：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --plan</span></span></code></pre></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code-cli/configuration/config-files.html">配置文件</a> — 所有可配置字段的完整参考</li><li><a href="/code/docs/kimi-code-cli/configuration/env-vars.html">环境变量</a> — <code>KIMI_CODE_HOME</code> 等变量的完整列表与说明</li></ul>`,37)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};